        $created = 0;
        $skipped = 0;

        foreach ($companies as $data) {
            // Check for existing company by slug
            $existing = Company::where('slug', $data['slug'])->first();
            if ($existing) {
                $skipped++;
                continue;
            }

            // Also check by name (case-insensitive)
            $existingByName = Company::whereRaw('LOWER(name) = ?', [strtolower($data['name'])])->first();
            if ($existingByName) {
                $skipped++;
                continue;
            }

            Company::create($data);
            $created++;
        }

        $this->command->info("GitHub Orgs Seeder: {$created} created, {$skipped} skipped (duplicates). Total in batch: ".count($companies));
    }
}
